class Worker(Timestamps):
    id: Annotated[str, Field(examples=["wrk_paddle"])]
    name: str
    kind: Literal["ocr", "layout", "image", "spreadsheet", "classifier", "custom"]
    base_url: AnyUrl
    adapter: Annotated[
        Literal["generic_pages_v1", "excel_parser_v1", "paddle_docparse_v1"],
        Field(
            description="How the backend calls the worker and normalises its response into `PagesResult`.\n- `generic_pages_v1`: POST multipart `file` to `invoke_path`; worker returns `PagesResult` directly.\n- `excel_parser_v1`: POST multipart `file` to `/to-text`; `{text_repr, sheet_names, total_cells, char_count}` is mapped to one text block per sheet.\n- `paddle_docparse_v1`: Paddle DocParse response (routes to confirm) mapped to blocks, tables and bounding boxes.\n"
        ),
    ]
    invoke_path: str | None = "/invoke"
    health_path: str | None = "/health"
    connection_id: Annotated[
        str | None, Field(description="Credentials used for every call (API key")
    ] = None
    accepts: Annotated[
        list[str] | None,
        Field(examples=[["application/pdf", "image/png", "image/tiff"]]),
    ] = None
    capabilities: Annotated[
        list[str] | None,
        Field(examples=[["text", "layout", "tables", "languages:en", "ar"]]),
    ] = None
    timeout_s: int | None = 60
    max_concurrency: int | None = 4
    data_region: str | None = None
    health: WorkerHealth | None = None


